FUNCTION handleDeleteTable(request, table_id):
    // REQ-4-016; preconditions: existing table and persistence available.
    REQUIRE admin OR RETURN 401 or 403; RETURN 404 for invalid or absent id. BEGIN TRANSACTION; IF reservation references table THEN ROLLBACK; RETURN 409. END IF MARK deleted; COMMIT; RETURN 204.
    // REQ-4-008; repeat is 404 and rollback preserves all state.

FUNCTION handleCancelWaitlistEntry(request, waitlist_id):
    // REQ-4-024; preconditions: existing WAITING or OFFERED entry and persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; RETURN 404 for invalid or absent id. BEGIN TRANSACTION; IF terminal entry THEN ROLLBACK; RETURN 409. END IF SET CANCELLED and release hold; COMMIT; RETURN 204.
    // REQ-4-005 and REQ-4-010; non-idempotent, rollback preserves capacity and history.

FUNCTION handlePatchTable(request, table_id):
    // REQ-4-015; preconditions: existing table, JSON, persistence available.
    REQUIRE admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE result OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF duplicate code, deactivation with holds, or new seats below active demand THEN ROLLBACK; RETURN 409. END IF UPDATE; COMMIT; RETURN 200.
    // Identical payload idempotent; rollback keeps capacity relations unchanged.

FUNCTION handleCreateReservation(request):
    // REQ-4-018; preconditions: JSON, active table, persistence available.
    REQUIRE user or admin OR RETURN 401; REQUIRE JSON OR RETURN 415; VALIDATE request OR RETURN 400 or 422; missing table is 404.
    BEGIN TRANSACTION; lock table and interval; IF REQ-4-004 capacity fails THEN ROLLBACK; RETURN 409. END IF CREATE BOOKED caller-owned row; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves availability and waitlist state.

FUNCTION handleCancelReservation(request, reservation_id):
    // REQ-4-020; preconditions: JSON, existing BOOKED reservation, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE cancellation and later offer expiry OR RETURN 400 or 422.
    BEGIN TRANSACTION; lock table, reservation, matching waitlist, and interval; IF not BOOKED THEN ROLLBACK; RETURN 409. END IF CANCEL reservation; OFFER lowest-id fitting WAITING entry on this table and store held_table_id if any; COMMIT; RETURN 200.
    // REQ-4-006; non-idempotent; rollback preserves cancellation, waitlist, and capacity state.

FUNCTION handleCreateTable(request):
    // REQ-4-013; preconditions: JSON and local persistence.
    REQUIRE admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE REQ-4-002 OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF code exists THEN ROLLBACK; RETURN 409. END IF CREATE table; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves reservations and waitlist relations.

FUNCTION handleCreateWaitlistEntry(request):
    // REQ-4-022; preconditions: JSON and persistence available.
    REQUIRE user or admin OR RETURN 401; REQUIRE JSON OR RETURN 415; VALIDATE request OR RETURN 400 or 422.
    BEGIN TRANSACTION; CREATE WAITING entry with caller; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves order and all availability relations.

FUNCTION handleAcceptWaitlistEntry(request, waitlist_id):
    // REQ-4-025; preconditions: JSON, existing OFFERED entry with held table, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE accepted_at OR RETURN 400 or 422.
    BEGIN TRANSACTION; lock entry, held table, and interval; IF not OFFERED, expiry passed, held table absent, or capacity fails THEN ROLLBACK; RETURN 409 or 404. END IF CREATE BOOKED reservation on held table; SET ACCEPTED; COMMIT; RETURN 201 with Location.
    // REQ-4-007; non-idempotent and rollback preserves hold and all relations.

FUNCTION handleExpireWaitlistEntry(request, waitlist_id):
    // REQ-4-026; preconditions: JSON, existing OFFERED entry, persistence available.
    REQUIRE admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE expired_at OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF not OFFERED or expired_at before offer expiry THEN ROLLBACK; RETURN 409. END IF SET EXPIRED and release hold; COMMIT; RETURN 200.
    // REQ-4-007; non-idempotent; rollback leaves capacity and history unchanged.
